write 'workflow-observability/resources/collector_job.yml' <<'WFOBS_EOF'
resources:
  jobs:
    collector:
      name: workflow-obs-collector
      description: Builds the observability layer (config -> silver -> gold) from system tables
      schedule:
        quartz_cron_expression: "0 0 */4 * * ?"   # every 4h; system tables lag a few hours
        timezone_id: UTC
      max_concurrent_runs: 1
      tags:
        team: platform
        product: workflow-observability

      # Job parameters are the single source of truth: the app reads them too.
      parameters:
        - name: catalog
          default: ${var.catalog}
        - name: lookback_days
          default: ${var.lookback_days}
        - name: auto_enable
          default: ${var.auto_enable_workspaces}
        - name: admin_emails
          default: ${var.admin_emails}

      environments:
        - environment_key: default
          spec:
            client: "2"

      tasks:
        - task_key: setup_and_discover
          environment_key: default
          spark_python_task:
            python_file: ../src/run_sql.py
            parameters:
              - "--catalog={{job.parameters.catalog}}"
              - "--lookback_days={{job.parameters.lookback_days}}"
              - "--auto_enable={{job.parameters.auto_enable}}"
              - "--files=00_setup.sql"

        - task_key: build_silver
          depends_on:
            - task_key: setup_and_discover
          environment_key: default
          spark_python_task:
            python_file: ../src/run_sql.py
            parameters:
              - "--catalog={{job.parameters.catalog}}"
              - "--lookback_days={{job.parameters.lookback_days}}"
              - "--files=10_silver.sql"

        - task_key: build_gold_and_findings
          depends_on:
            - task_key: build_silver
          environment_key: default
          spark_python_task:
            python_file: ../src/run_sql.py
            parameters:
              - "--catalog={{job.parameters.catalog}}"
              - "--lookback_days={{job.parameters.lookback_days}}"
              - "--files=20_gold.sql"
WFOBS_EOF

write 'workflow-observability/src/run_sql.py' <<'WFOBS_EOF'
"""Run the layer's SQL files on serverless jobs compute.

Placeholders ${catalog}, ${lookback_days}, ${auto_enable} are substituted.
Statements are separated by a line ending in ';'.
A statement containing '-- @optional' is allowed to fail (e.g. a system
table not enabled in this account) without failing the job.
"""
import argparse
import os
import re

from pyspark.sql import SparkSession

SQL_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sql")


def parse_args():
    p = argparse.ArgumentParser()
    p.add_argument("--catalog", required=True)
    p.add_argument("--lookback_days", type=int, default=3)
    p.add_argument("--auto_enable", default="true")
    p.add_argument("--files", required=True, help="comma-separated file names in src/sql")
    return p.parse_args()


def statements(text):
    for chunk in re.split(r";[ \t]*$", text, flags=re.MULTILINE):
        body = "\n".join(l for l in chunk.splitlines() if not l.strip().startswith("--") or "@optional" in l)
        if body.strip():
            yield chunk.strip(), "@optional" in chunk


def main():
    a = parse_args()
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", a.catalog):
        raise ValueError(f"invalid catalog name: {a.catalog}")
    auto_enable = "true" if a.auto_enable.lower() == "true" else "false"
    subs = {"catalog": a.catalog, "lookback_days": str(max(1, a.lookback_days)), "auto_enable": auto_enable}

    spark = SparkSession.builder.getOrCreate()
    for name in a.files.split(","):
        with open(os.path.join(SQL_DIR, name.strip())) as f:
            text = f.read()
        for k, v in subs.items():
            text = text.replace("${" + k + "}", v)
        for i, (stmt, optional) in enumerate(statements(text), 1):
            print(f"[{name} #{i}] running")
            try:
                spark.sql(stmt)
            except Exception as e:  # noqa: BLE001
                if optional:
                    print(f"[{name} #{i}] optional statement skipped: {e}")
                else:
                    raise


if __name__ == "__main__":
    main()
WFOBS_EOF

write 'workflow-observability/src/sql/00_setup.sql' <<'WFOBS_EOF'
-- =============================================================
-- 00 SETUP: schemas, config tables, workspace auto-discovery
-- =============================================================
CREATE SCHEMA IF NOT EXISTS ${catalog}.config;
CREATE SCHEMA IF NOT EXISTS ${catalog}.silver;
CREATE SCHEMA IF NOT EXISTS ${catalog}.gold;

-- Workspace registry: every workspace seen in billing lands here.
-- Admins edit name / environment / owner / enabled from the app.
CREATE TABLE IF NOT EXISTS ${catalog}.config.workspaces (
  workspace_id   STRING,
  workspace_name STRING,
  environment    STRING,
  owner_team     STRING,
  enabled        BOOLEAN,
  first_seen     DATE,
  updated_at     TIMESTAMP
);

-- Optimization rules: thresholds are data, not code.
CREATE TABLE IF NOT EXISTS ${catalog}.config.rules (
  rule_id        STRING,
  title          STRING,
  threshold      DOUBLE,
  severity       STRING,
  enabled        BOOLEAN,
  recommendation STRING
);

-- Key/value settings (e.g. negotiated discount vs list price)
CREATE TABLE IF NOT EXISTS ${catalog}.config.settings (
  key   STRING,
  value STRING
);

MERGE INTO ${catalog}.config.settings t
USING (SELECT * FROM VALUES ('discount_pct', '0') AS v(key, value)) s
ON t.key = s.key
WHEN NOT MATCHED THEN INSERT *;

MERGE INTO ${catalog}.config.rules t
USING (
  SELECT * FROM VALUES
    ('LOW_CPU',            'Over-provisioned job cluster (avg CPU %)',      30.0,  'HIGH',   true, 'Downsize node type / workers, enable autoscaling, or move to serverless.'),
    ('HIGH_FAILURE_COST',  'Spend on failed runs (USD, 30d)',               50.0,  'HIGH',   true, 'Fix top termination codes; add retries only for transient errors.'),
    ('HIGH_SETUP_OVERHEAD','Cluster startup share of task time (%)',        25.0,  'MEDIUM', true, 'Use serverless, instance pools, or share one job cluster across tasks.'),
    ('ALL_PURPOSE_COMPUTE','Task runs on all-purpose clusters (30d)',        0.0,  'HIGH',   true, 'Switch tasks to job clusters or serverless - all-purpose DBUs cost more.'),
    ('COST_SPIKE',         'Week-over-week cost growth (%)',                50.0,  'MEDIUM', true, 'Check for data volume change, config drift or added schedules.'),
    ('UNTAGGED_SPEND',     'Spend without custom tags (USD, 30d)',         100.0,  'LOW',    true, 'Add team / cost_center tags for chargeback.'),
    ('LOW_SUCCESS_RATE',   'Run success rate below (%)',                    90.0,  'MEDIUM', true, 'Review failing tasks and upstream dependencies.')
  AS v(rule_id, title, threshold, severity, enabled, recommendation)
) s
ON t.rule_id = s.rule_id
WHEN NOT MATCHED THEN INSERT *;

-- Auto-discover workspaces from billing (account-wide, this region)
MERGE INTO ${catalog}.config.workspaces t
USING (
  SELECT workspace_id, MIN(usage_date) AS first_seen
  FROM system.billing.usage
  WHERE usage_date >= date_sub(current_date(), 30)
  GROUP BY workspace_id
) s
ON t.workspace_id = s.workspace_id
WHEN NOT MATCHED THEN INSERT
  (workspace_id, workspace_name, environment, owner_team, enabled, first_seen, updated_at)
  VALUES (s.workspace_id, NULL, NULL, NULL, ${auto_enable}, s.first_seen, current_timestamp());

-- Fill in workspace names where the account exposes them  -- @optional
MERGE INTO ${catalog}.config.workspaces t
USING (SELECT CAST(workspace_id AS STRING) AS workspace_id, workspace_name FROM system.access.workspaces_latest) s
ON t.workspace_id = s.workspace_id
WHEN MATCHED AND t.workspace_name IS NULL THEN UPDATE SET workspace_name = s.workspace_name, updated_at = current_timestamp();
WFOBS_EOF

write 'workflow-observability/src/sql/10_silver.sql' <<'WFOBS_EOF'
-- =============================================================
-- 10 SILVER: curated, incremental facts for enabled workspaces
-- Each run re-merges the last ${lookback_days} days so late
-- billing corrections and long-running jobs are picked up.
-- First deploy: run once with --lookback_days=90 to backfill.
-- =============================================================

-- ---------- usage + cost (one row per billing record) ----------
CREATE TABLE IF NOT EXISTS ${catalog}.silver.fact_usage_cost (
  record_id              STRING,
  workspace_id           STRING,
  usage_date             DATE,
  usage_start_time       TIMESTAMP,
  usage_end_time         TIMESTAMP,
  sku_name               STRING,
  billing_origin_product STRING,
  job_id                 STRING,
  run_id                 STRING,
  cluster_id             STRING,
  warehouse_id           STRING,
  run_as                 STRING,
  is_serverless          BOOLEAN,
  is_photon              BOOLEAN,
  has_tags               BOOLEAN,
  dbus                   DOUBLE,
  list_cost              DOUBLE,
  effective_cost         DOUBLE
) CLUSTER BY (workspace_id, usage_date);

MERGE INTO ${catalog}.silver.fact_usage_cost t
USING (
  SELECT
    u.record_id,
    u.workspace_id,
    u.usage_date,
    u.usage_start_time,
    u.usage_end_time,
    u.sku_name,
    u.billing_origin_product,
    u.usage_metadata.job_id,
    u.usage_metadata.job_run_id                         AS run_id,
    u.usage_metadata.cluster_id,
    u.usage_metadata.warehouse_id,
    u.identity_metadata.run_as,
    COALESCE(u.product_features.is_serverless, false)   AS is_serverless,
    COALESCE(u.product_features.is_photon, false)       AS is_photon,
    (u.custom_tags IS NOT NULL AND cardinality(u.custom_tags) > 0) AS has_tags,
    CAST(u.usage_quantity AS DOUBLE)                    AS dbus,
    CAST(u.usage_quantity * lp.pricing.default AS DOUBLE)                         AS list_cost,
    CAST(u.usage_quantity * lp.pricing.default AS DOUBLE) * (1 - d.disc / 100.0)  AS effective_cost
  FROM system.billing.usage u
  LEFT JOIN system.billing.list_prices lp
    ON  u.sku_name = lp.sku_name
    AND u.cloud = lp.cloud
    AND u.usage_unit = lp.usage_unit
    AND u.usage_end_time >= lp.price_start_time
    AND (lp.price_end_time IS NULL OR u.usage_end_time < lp.price_end_time)
  CROSS JOIN (
    SELECT COALESCE(MAX(CAST(value AS DOUBLE)), 0) AS disc
    FROM ${catalog}.config.settings WHERE key = 'discount_pct'
  ) d
  WHERE u.usage_date >= date_sub(current_date(), ${lookback_days})
    AND u.workspace_id IN (SELECT workspace_id FROM ${catalog}.config.workspaces WHERE enabled)
) s
ON t.record_id = s.record_id
WHEN MATCHED THEN UPDATE SET *
WHEN NOT MATCHED THEN INSERT *;

-- ---------- latest job definitions ----------
CREATE OR REPLACE TABLE ${catalog}.silver.dim_job AS
SELECT workspace_id, job_id, name AS job_name, creator_id, tags, change_time, delete_time
FROM system.lakeflow.jobs
WHERE workspace_id IN (SELECT workspace_id FROM ${catalog}.config.workspaces WHERE enabled)
QUALIFY ROW_NUMBER() OVER (PARTITION BY workspace_id, job_id ORDER BY change_time DESC) = 1;

-- ---------- latest cluster definitions (last 90d) ----------
CREATE OR REPLACE TABLE ${catalog}.silver.dim_cluster AS
SELECT workspace_id, cluster_id, cluster_name, cluster_source, owned_by, dbr_version,
       driver_node_type, worker_node_type, worker_count,
       min_autoscale_workers, max_autoscale_workers, change_time
FROM system.compute.clusters
WHERE change_time >= date_sub(current_date(), 90)
  AND workspace_id IN (SELECT workspace_id FROM ${catalog}.config.workspaces WHERE enabled)
QUALIFY ROW_NUMBER() OVER (PARTITION BY workspace_id, cluster_id ORDER BY change_time DESC) = 1;

-- ---------- one row per job run ----------
CREATE TABLE IF NOT EXISTS ${catalog}.silver.fact_job_run (
  workspace_id     STRING,
  job_id           STRING,
  run_id           STRING,
  run_name         STRING,
  trigger_type     STRING,
  run_type         STRING,
  start_time       TIMESTAMP,
  end_time         TIMESTAMP,
  duration_min     DOUBLE,
  result_state     STRING,
  termination_code STRING,
  repairs          INT,
  run_as           STRING,
  list_cost        DOUBLE,
  effective_cost   DOUBLE
) CLUSTER BY (workspace_id, start_time);

MERGE INTO ${catalog}.silver.fact_job_run t
USING (
  WITH touched AS (            -- runs with any activity in the window
    SELECT DISTINCT workspace_id, run_id
    FROM system.lakeflow.job_run_timeline
    WHERE period_end_time >= date_sub(current_date(), ${lookback_days})
      AND workspace_id IN (SELECT workspace_id FROM ${catalog}.config.workspaces WHERE enabled)
  ),
  r AS (
    SELECT
      t.workspace_id, t.job_id, t.run_id,
      MAX(t.run_name)      AS run_name,
      MAX(t.trigger_type)  AS trigger_type,
      MAX(t.run_type)      AS run_type,
      MIN(t.period_start_time) AS start_time,
      MAX(t.period_end_time)   AS end_time,
      MAX_BY(t.result_state, t.period_end_time)     AS result_state,
      MAX_BY(t.termination_code, t.period_end_time) AS termination_code,
      CAST(GREATEST(COUNT_IF(t.result_state IS NOT NULL) - 1, 0) AS INT) AS repairs
    FROM system.lakeflow.job_run_timeline t
    JOIN touched USING (workspace_id, run_id)
    GROUP BY t.workspace_id, t.job_id, t.run_id
  ),
  c AS (
    SELECT workspace_id, run_id,
           FIRST(run_as, true) AS run_as,
           SUM(list_cost)      AS list_cost,
           SUM(effective_cost) AS effective_cost
    FROM ${catalog}.silver.fact_usage_cost
    WHERE run_id IS NOT NULL
      AND usage_date >= date_sub(current_date(), ${lookback_days} + 7)
    GROUP BY workspace_id, run_id
  )
  SELECT r.workspace_id, r.job_id, r.run_id, r.run_name, r.trigger_type, r.run_type,
         r.start_time, r.end_time,
         (unix_timestamp(r.end_time) - unix_timestamp(r.start_time)) / 60.0 AS duration_min,
         r.result_state, r.termination_code, r.repairs,
         c.run_as, COALESCE(c.list_cost, 0) AS list_cost, COALESCE(c.effective_cost, 0) AS effective_cost
  FROM r LEFT JOIN c USING (workspace_id, run_id)
) s
ON t.workspace_id = s.workspace_id AND t.run_id = s.run_id
WHEN MATCHED THEN UPDATE SET *
WHEN NOT MATCHED THEN INSERT *;

-- ---------- one row per task run ----------
CREATE TABLE IF NOT EXISTS ${catalog}.silver.fact_task_run (
  workspace_id     STRING,
  job_id           STRING,
  job_run_id       STRING,
  task_run_id      STRING,
  task_key         STRING,
  start_time       TIMESTAMP,
  end_time         TIMESTAMP,
  result_state     STRING,
  termination_code STRING,
  setup_s          DOUBLE,
  queue_s          DOUBLE,
  exec_s           DOUBLE,
  compute_ids      ARRAY<STRING>
) CLUSTER BY (workspace_id, start_time);

MERGE INTO ${catalog}.silver.fact_task_run t
USING (
  WITH touched AS (
    SELECT DISTINCT workspace_id, run_id
    FROM system.lakeflow.job_task_run_timeline
    WHERE period_end_time >= date_sub(current_date(), ${lookback_days})
      AND workspace_id IN (SELECT workspace_id FROM ${catalog}.config.workspaces WHERE enabled)
  )
  SELECT
    t.workspace_id, t.job_id,
    MAX(t.job_run_id)                AS job_run_id,
    t.run_id                         AS task_run_id,
    MAX(t.task_key)                  AS task_key,
    MIN(t.period_start_time)         AS start_time,
    MAX(t.period_end_time)           AS end_time,
    MAX_BY(t.result_state, t.period_end_time)     AS result_state,
    MAX_BY(t.termination_code, t.period_end_time) AS termination_code,
    CAST(SUM(COALESCE(t.setup_duration_seconds, 0))     AS DOUBLE) AS setup_s,
    CAST(SUM(COALESCE(t.queue_duration_seconds, 0))     AS DOUBLE) AS queue_s,
    CAST(SUM(COALESCE(t.execution_duration_seconds, 0)) AS DOUBLE) AS exec_s,
    array_distinct(flatten(collect_list(t.compute_ids))) AS compute_ids
  FROM system.lakeflow.job_task_run_timeline t
  JOIN touched USING (workspace_id, run_id)
  GROUP BY t.workspace_id, t.job_id, t.run_id
) s
ON t.workspace_id = s.workspace_id AND t.task_run_id = s.task_run_id
WHEN MATCHED THEN UPDATE SET *
WHEN NOT MATCHED THEN INSERT *;

-- ---------- daily worker utilization per cluster ----------
CREATE TABLE IF NOT EXISTS ${catalog}.silver.fact_cluster_util (
  workspace_id    STRING,
  cluster_id      STRING,
  util_date       DATE,
  avg_cpu_pct     DOUBLE,
  peak_cpu_pct    DOUBLE,
  avg_mem_pct     DOUBLE,
  avg_io_wait_pct DOUBLE
) CLUSTER BY (workspace_id, util_date);

MERGE INTO ${catalog}.silver.fact_cluster_util t
USING (
  SELECT workspace_id, cluster_id, to_date(start_time) AS util_date,
         AVG(cpu_user_percent + cpu_system_percent) AS avg_cpu_pct,
         MAX(cpu_user_percent + cpu_system_percent) AS peak_cpu_pct,
         AVG(mem_used_percent)                      AS avg_mem_pct,
         AVG(cpu_wait_percent)                      AS avg_io_wait_pct
  FROM system.compute.node_timeline
  WHERE start_time >= date_sub(current_date(), ${lookback_days})
    AND driver = false
    AND workspace_id IN (SELECT workspace_id FROM ${catalog}.config.workspaces WHERE enabled)
  GROUP BY workspace_id, cluster_id, to_date(start_time)
) s
ON t.workspace_id = s.workspace_id AND t.cluster_id = s.cluster_id AND t.util_date = s.util_date
WHEN MATCHED THEN UPDATE SET *
WHEN NOT MATCHED THEN INSERT *;
WFOBS_EOF

write 'workflow-observability/src/sql/20_gold.sql' <<'WFOBS_EOF'
-- =============================================================
-- 20 GOLD: KPI views, 30-day job summary, optimization findings
-- =============================================================

-- Daily cost by workspace / product / SKU (the app filters this)
CREATE OR REPLACE VIEW ${catalog}.gold.v_daily_cost AS
SELECT u.usage_date, u.workspace_id,
       COALESCE(w.workspace_name, u.workspace_id) AS workspace_name,
       u.billing_origin_product, u.sku_name, u.is_serverless,
       SUM(u.dbus) AS dbus, SUM(u.list_cost) AS list_cost, SUM(u.effective_cost) AS effective_cost
FROM ${catalog}.silver.fact_usage_cost u
LEFT JOIN ${catalog}.config.workspaces w USING (workspace_id)
GROUP BY ALL;

-- One row per job with everything the rules need (last 30 days)
CREATE OR REPLACE TABLE ${catalog}.gold.job_summary_30d AS
WITH runs AS (
  SELECT workspace_id, job_id,
         COUNT(*)                                                    AS runs,
         COUNT_IF(result_state = 'SUCCEEDED')                        AS succeeded,
         COUNT_IF(result_state IN ('FAILED','ERROR','TIMED_OUT'))    AS failed,
         SUM(effective_cost)                                         AS cost_30d,
         SUM(CASE WHEN result_state IN ('FAILED','ERROR','TIMED_OUT') THEN effective_cost ELSE 0 END) AS failed_cost,
         AVG(duration_min)                                           AS avg_duration_min,
         SUM(repairs)                                                AS repairs,
         MAX(run_as)                                                 AS run_as,
         MAX(start_time)                                             AS last_run
  FROM ${catalog}.silver.fact_job_run
  WHERE start_time >= date_sub(current_date(), 30)
  GROUP BY workspace_id, job_id
),
usage AS (
  SELECT workspace_id, job_id,
         SUM(CASE WHEN usage_date >= date_sub(current_date(), 7) THEN effective_cost ELSE 0 END) AS last7,
         SUM(CASE WHEN usage_date <  date_sub(current_date(), 7)
                   AND usage_date >= date_sub(current_date(), 14) THEN effective_cost ELSE 0 END) AS prev7,
         SUM(CASE WHEN NOT has_tags THEN effective_cost ELSE 0 END)     AS untagged_cost,
         SUM(CASE WHEN is_serverless THEN effective_cost ELSE 0 END) / NULLIF(SUM(effective_cost), 0) AS serverless_share
  FROM ${catalog}.silver.fact_usage_cost
  WHERE billing_origin_product = 'JOBS' AND job_id IS NOT NULL
    AND usage_date >= date_sub(current_date(), 30)
  GROUP BY workspace_id, job_id
),
tasks AS (
  SELECT workspace_id, job_id,
         100 * SUM(setup_s) / NULLIF(SUM(setup_s + exec_s), 0) AS setup_pct,
         SUM(queue_s) / 60.0                                   AS queue_min
  FROM ${catalog}.silver.fact_task_run
  WHERE start_time >= date_sub(current_date(), 30)
  GROUP BY workspace_id, job_id
),
util AS (
  SELECT jc.workspace_id, jc.job_id,
         AVG(cu.avg_cpu_pct)  AS avg_cpu_pct,
         MAX(cu.peak_cpu_pct) AS peak_cpu_pct,
         AVG(cu.avg_mem_pct)  AS avg_mem_pct
  FROM (SELECT DISTINCT workspace_id, job_id, cluster_id
        FROM ${catalog}.silver.fact_usage_cost
        WHERE job_id IS NOT NULL AND cluster_id IS NOT NULL
          AND usage_date >= date_sub(current_date(), 30)) jc
  JOIN ${catalog}.silver.fact_cluster_util cu
    ON cu.workspace_id = jc.workspace_id AND cu.cluster_id = jc.cluster_id
   AND cu.util_date >= date_sub(current_date(), 30)
  GROUP BY jc.workspace_id, jc.job_id
),
all_purpose AS (
  SELECT t.workspace_id, t.job_id, COUNT(DISTINCT t.job_run_id) AS ap_runs
  FROM ${catalog}.silver.fact_task_run t
  LATERAL VIEW explode(t.compute_ids) x AS compute_id
  JOIN ${catalog}.silver.dim_cluster c
    ON c.workspace_id = t.workspace_id AND c.cluster_id = x.compute_id
   AND c.cluster_source IN ('UI', 'API')
  WHERE t.start_time >= date_sub(current_date(), 30)
  GROUP BY t.workspace_id, t.job_id
)
SELECT
  r.workspace_id,
  COALESCE(w.workspace_name, r.workspace_id)            AS workspace_name,
  w.environment, w.owner_team,
  r.job_id,
  COALESCE(j.job_name, concat('job ', r.job_id))        AS job_name,
  r.run_as, r.runs, r.succeeded, r.failed, r.repairs, r.last_run,
  ROUND(100.0 * r.succeeded / NULLIF(r.runs, 0), 1)     AS success_pct,
  ROUND(r.cost_30d, 2)                                  AS cost_30d,
  ROUND(r.cost_30d / NULLIF(r.runs, 0), 2)              AS cost_per_run,
  ROUND(r.failed_cost, 2)                               AS failed_cost,
  ROUND(r.avg_duration_min, 1)                          AS avg_duration_min,
  ROUND(u.last7, 2) AS last7_cost, ROUND(u.prev7, 2) AS prev7_cost,
  ROUND(100.0 * (u.last7 - u.prev7) / NULLIF(u.prev7, 0), 1) AS growth_pct,
  ROUND(u.untagged_cost, 2)                             AS untagged_cost,
  ROUND(COALESCE(u.serverless_share, 0), 2)             AS serverless_share,
  ROUND(t.setup_pct, 1)                                 AS setup_pct,
  ROUND(t.queue_min, 1)                                 AS queue_min,
  ROUND(ut.avg_cpu_pct, 1)  AS avg_cpu_pct,
  ROUND(ut.peak_cpu_pct, 1) AS peak_cpu_pct,
  ROUND(ut.avg_mem_pct, 1)  AS avg_mem_pct,
  COALESCE(ap.ap_runs, 0)                               AS all_purpose_runs
FROM runs r
LEFT JOIN usage u        USING (workspace_id, job_id)
LEFT JOIN tasks t        USING (workspace_id, job_id)
LEFT JOIN util ut        USING (workspace_id, job_id)
LEFT JOIN all_purpose ap USING (workspace_id, job_id)
LEFT JOIN ${catalog}.silver.dim_job j USING (workspace_id, job_id)
LEFT JOIN ${catalog}.config.workspaces w USING (workspace_id);

-- Findings: one row per (job, rule) breach. Savings are rough estimates.
CREATE OR REPLACE TABLE ${catalog}.gold.findings AS
WITH m AS (
  -- one candidate row per (job, rule) with the metric the rule checks
  SELECT s.*, f.rid, f.metric_value, f.est
  FROM ${catalog}.gold.job_summary_30d s
  LATERAL VIEW inline(array(
    named_struct('rid','LOW_CPU',             'metric_value', CAST(s.avg_cpu_pct AS DOUBLE),
                 'est', CAST(s.cost_30d * (1 - s.serverless_share) * 0.3 AS DOUBLE)),
    named_struct('rid','HIGH_FAILURE_COST',   'metric_value', CAST(s.failed_cost AS DOUBLE),
                 'est', CAST(s.failed_cost AS DOUBLE)),
    named_struct('rid','HIGH_SETUP_OVERHEAD', 'metric_value', CAST(s.setup_pct AS DOUBLE),
                 'est', CAST(s.cost_30d * s.setup_pct / 100 * 0.5 AS DOUBLE)),
    named_struct('rid','ALL_PURPOSE_COMPUTE', 'metric_value', CAST(s.all_purpose_runs AS DOUBLE),
                 'est', CAST(NULL AS DOUBLE)),
    named_struct('rid','COST_SPIKE',          'metric_value', CAST(s.growth_pct AS DOUBLE),
                 'est', CAST(NULL AS DOUBLE)),
    named_struct('rid','UNTAGGED_SPEND',      'metric_value', CAST(s.untagged_cost AS DOUBLE),
                 'est', CAST(NULL AS DOUBLE)),
    named_struct('rid','LOW_SUCCESS_RATE',    'metric_value', CAST(s.success_pct AS DOUBLE),
                 'est', CAST(NULL AS DOUBLE))
  )) f AS rid, metric_value, est
)
SELECT m.workspace_id, m.workspace_name, m.owner_team, m.job_id, m.job_name,
       r.rule_id, r.title, r.severity,
       ROUND(m.metric_value, 1) AS metric_value, r.threshold,
       ROUND(m.est, 2)          AS est_monthly_savings,
       r.recommendation, current_timestamp() AS detected_at
FROM m
JOIN ${catalog}.config.rules r ON r.rule_id = m.rid AND r.enabled
WHERE m.metric_value IS NOT NULL
  AND CASE r.rule_id
        WHEN 'LOW_CPU'          THEN m.metric_value < r.threshold AND m.cost_30d > 0
        WHEN 'LOW_SUCCESS_RATE' THEN m.metric_value < r.threshold AND m.runs >= 5
        WHEN 'COST_SPIKE'       THEN m.metric_value > r.threshold AND m.prev7_cost > 10
        ELSE m.metric_value > r.threshold
      END;
WFOBS_EOF

write 'workflow-observability/.github/workflows/deploy.yml' <<'WFOBS_EOF'
name: deploy-workflow-observability

on:
  push:
    branches: [main]
    paths: ['workflow-observability/**', '.github/workflows/deploy.yml']
  pull_request:
    paths: ['workflow-observability/**']
  workflow_dispatch:

defaults:
  run:
    working-directory: workflow-observability

jobs:
  validate:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: databricks/setup-cli@main
      - run: databricks bundle validate -t dev
        env:
          DATABRICKS_HOST: ${{ secrets.DEV_DATABRICKS_HOST }}
          DATABRICKS_CLIENT_ID: ${{ secrets.DEV_DATABRICKS_CLIENT_ID }}
          DATABRICKS_CLIENT_SECRET: ${{ secrets.DEV_DATABRICKS_CLIENT_SECRET }}

  deploy-prod:
    if: github.ref == 'refs/heads/main' && github.event_name != 'pull_request'
    needs: validate
    runs-on: ubuntu-latest
    strategy:
      matrix:
        target: [prod_us_east_1]          # add one entry per regional hub
    environment: ${{ matrix.target }}
    steps:
      - uses: actions/checkout@v4
      - uses: databricks/setup-cli@main
      - run: |
          databricks bundle deploy -t ${{ matrix.target }}
          databricks bundle run workflow_obs_app -t ${{ matrix.target }}
        env:
          DATABRICKS_HOST: ${{ secrets.DATABRICKS_HOST }}
          DATABRICKS_CLIENT_ID: ${{ secrets.DATABRICKS_CLIENT_ID }}
          DATABRICKS_CLIENT_SECRET: ${{ secrets.DATABRICKS_CLIENT_SECRET }}
WFOBS_EOF

echo
echo "Done. $(find workflow-observability -type f | wc -l | tr -d " ") files created."
echo "Next: open workflow-observability/STEP_BY_STEP.md and start at Step 2."
echo "Note: .github/ is placed inside workflow-observability/; move it to your repo root if you use GitHub Actions."
